INSERT INTO public.riscos_biblioteca (codigo, titulo, descricao, categoria, causas, consequencias, probabilidade_sugerida, impacto_sugerido, tipos_ativo, controlos_recomendados, origem, tags) VALUES
('BIB-ORG-01','Inexistência de políticas formais de segurança da informação','A organização opera sem políticas de segurança aprovadas pela gestão de topo e comunicadas aos utilizadores. As regras existem apenas por hábito, o que impede exigir cumprimento e demonstrar conformidade a clientes e auditores.','Organizacional',ARRAY['Ausência de patrocínio da gestão de topo','Falta de responsável formal pela segurança da informação','Crescimento rápido sem estruturação documental'],ARRAY['Impossibilidade de responsabilizar utilizadores por incumprimento','Reprovação em auditorias e questionários de clientes','Decisões de segurança inconsistentes entre equipas'],4,4,ARRAY['pessoas','fornecedor'],ARRAY['A.5.1','A.5.2','A.5.4','A.5.37'],'ISO 27001',ARRAY['governanca','politicas']),
('BIB-ORG-02','Papéis e responsabilidades de segurança não atribuídos','Não existe definição documentada de quem responde pela segurança da informação, pela proteção de dados e pela resposta a incidentes. Em caso de evento, ninguém sabe quem decide.','Organizacional',ARRAY['Estrutura organizacional informal','Acumulação de funções em TI sem mandato formal'],ARRAY['Atraso na resposta a incidentes','Tarefas críticas de segurança por executar','Conflito de interesses entre execução e controlo'],4,3,ARRAY['pessoas'],ARRAY['A.5.2','A.5.3','A.5.4'],'ISO 27001',ARRAY['governanca','papeis']),
('BIB-ORG-03','Ausência de inventário de ativos de informação','A organização desconhece a totalidade dos seus servidores, portáteis, aplicações e serviços cloud. Sem inventário, o âmbito da proteção é sempre incompleto.','Organizacional',ARRAY['Aquisições descentralizadas','Inexistência de processo de registo de ativos','Rotatividade de equipamento sem baixa formal'],ARRAY['Equipamentos sem atualizações nem antivírus','Licenças e subscrições a pagar sem utilização','Impossibilidade de avaliar impacto de um incidente'],4,3,ARRAY['servidor','estacao de trabalho','portatil','cloud/SaaS','aplicacao web'],ARRAY['A.5.9','A.5.10','A.5.11','A.8.1'],'ISO 27001',ARRAY['ativos','inventario']),
('BIB-ORG-04','Classificação da informação inexistente','A informação não é classificada quanto à confidencialidade, pelo que documentos sensíveis circulam com o mesmo tratamento de documentos públicos.','Organizacional',ARRAY['Falta de esquema de classificação aprovado','Ausência de formação sobre manuseamento de informação'],ARRAY['Divulgação indevida de informação confidencial','Aplicação de controlos desproporcionados ou insuficientes'],3,3,ARRAY['aplicacao web','cloud/SaaS','pessoas'],ARRAY['A.5.12','A.5.13','A.5.14'],'ISO 27001',ARRAY['classificacao']),
('BIB-ORG-05','Fornecedor crítico sem cláusulas de segurança no contrato','Serviços essenciais estão entregues a fornecedores cujos contratos não incluem obrigações de segurança, notificação de incidentes nem direito a auditoria.','Organizacional',ARRAY['Contratação focada apenas em preço e prazo','Ausência de modelo contratual com anexo de segurança','Renovações automáticas sem revisão'],ARRAY['Incidente no fornecedor sem obrigação de comunicação','Ausência de recurso contratual em caso de fuga de dados','Dependência sem garantias de continuidade'],4,4,ARRAY['fornecedor','cloud/SaaS'],ARRAY['A.5.19','A.5.20','A.5.21','A.5.22'],'Ambos',ARRAY['fornecedores','terceiros']),
('BIB-ORG-06','Ausência de avaliação e monitorização de fornecedores','Os fornecedores são contratados sem avaliação de segurança prévia e nunca mais são reavaliados durante a vigência do contrato.','Organizacional',ARRAY['Inexistência de processo de due diligence','Falta de recursos para acompanhamento'],ARRAY['Degradação silenciosa do nível de serviço e de segurança','Descoberta tardia de subcontratação não autorizada'],4,3,ARRAY['fornecedor'],ARRAY['A.5.19','A.5.22','A.5.23'],'Ambos',ARRAY['fornecedores','due diligence']),
('BIB-ORG-07','Serviços cloud adquiridos sem avaliação de segurança','Subscrições de serviços na nuvem são contratadas por áreas de negócio sem análise de localização dos dados, cifra ou compromissos de disponibilidade.','Organizacional',ARRAY['Facilidade de aquisição por cartão de crédito','Ausência de política de utilização de serviços cloud'],ARRAY['Dados corporativos alojados fora do controlo da organização','Transferências internacionais sem base legal'],4,4,ARRAY['cloud/SaaS'],ARRAY['A.5.23','A.5.19','A.5.10'],'Ambos',ARRAY['cloud','shadow it']),
('BIB-ORG-08','Shadow IT: ferramentas usadas sem aprovação','Colaboradores recorrem a aplicações e serviços gratuitos para trabalhar, colocando ficheiros da organização em contas pessoais fora de qualquer controlo.','Organizacional',ARRAY['Ferramentas oficiais insuficientes ou lentas a aprovar','Falta de política de utilização aceitável','Ausência de monitorização do tráfego de saída'],ARRAY['Perda de controlo sobre ficheiros da organização','Impossibilidade de recuperar dados após saída do colaborador','Incumprimento do RGPD por tratamento não registado'],4,3,ARRAY['estacao de trabalho','cloud/SaaS','dispositivo movel'],ARRAY['A.5.10','A.8.19','A.5.23','A.6.3'],'Ambos',ARRAY['shadow it','cloud']),
('BIB-ORG-09','Processo de gestão de incidentes inexistente','Não existe procedimento definido para reportar, classificar, escalar e encerrar incidentes de segurança. Os eventos são resolvidos caso a caso e sem registo.','Organizacional',ARRAY['Ausência de plano de resposta a incidentes','Falta de canal de reporte conhecido pelos utilizadores'],ARRAY['Resposta lenta e desorganizada','Perda de prova para investigação e para seguros','Incumprimento de prazos legais de notificação'],4,4,ARRAY['pessoas','servidor','aplicacao web'],ARRAY['A.5.24','A.5.25','A.5.26','A.5.27','A.6.8'],'Ambos',ARRAY['incidentes']),
('BIB-ORG-10','Ausência de plano de continuidade de negócio','A organização não tem plano documentado nem testado para manter as atividades críticas em caso de indisponibilidade prolongada dos sistemas.','Organizacional',ARRAY['Análise de impacto no negócio nunca realizada','Pressupostos de recuperação nunca validados'],ARRAY['Paragem prolongada da atividade','Decisões improvisadas em crise','Perda de clientes e de receita'],3,5,ARRAY['servidor','cloud/SaaS','instalacao fisica'],ARRAY['A.5.29','A.5.30','A.8.14'],'ISO 27001',ARRAY['continuidade']),
('BIB-ORG-11','Requisitos legais e contratuais não identificados','A organização não mantém lista atualizada das obrigações legais, regulamentares e contratuais aplicáveis à segurança da informação.','Organizacional',ARRAY['Ausência de acompanhamento jurídico','Entrada em novos mercados sem análise'],ARRAY['Incumprimento legal detetado apenas em fiscalização','Coimas e penalizações contratuais'],3,4,ARRAY['pessoas'],ARRAY['A.5.31','A.5.32','A.5.34','A.5.36'],'Ambos',ARRAY['conformidade','legal']),
('BIB-ORG-12','Ausência de auditorias internas de segurança','Os controlos nunca são verificados de forma independente, pelo que falhas persistem sem deteção até uma auditoria externa ou um incidente.','Organizacional',ARRAY['Falta de plano de auditoria interna','Recursos afetos apenas a operação'],ARRAY['Controlos ineficazes durante longos períodos','Não conformidades acumuladas na certificação'],3,3,ARRAY['pessoas'],ARRAY['A.5.35','A.5.36'],'ISO 27001',ARRAY['auditoria']),
('BIB-ORG-13','Propriedade intelectual e licenciamento de software não controlados','São utilizados programas sem licença válida ou fora das condições de utilização, incluindo software descarregado por iniciativa dos utilizadores.','Organizacional',ARRAY['Ausência de gestão de licenças','Utilizadores com permissões para instalar programas'],ARRAY['Coimas por utilização ilegítima de software','Instalação de programas com código malicioso'],3,3,ARRAY['estacao de trabalho','portatil','servidor'],ARRAY['A.5.32','A.8.19','A.5.10'],'ISO 27001',ARRAY['licencas']),
('BIB-ORG-14','Ausência de política de utilização aceitável dos ativos','Não estão definidas regras sobre a utilização de equipamentos, correio eletrónico, internet e dados da organização, incluindo utilização pessoal.','Organizacional',ARRAY['Documentação de suporte inexistente','Falta de aceitação formal pelos utilizadores'],ARRAY['Utilização indevida sem consequência disciplinar possível','Exposição a conteúdos e serviços de risco'],4,3,ARRAY['estacao de trabalho','portatil','dispositivo movel'],ARRAY['A.5.10','A.6.2','A.6.3'],'ISO 27001',ARRAY['politicas','utilizacao']),
('BIB-ORG-15','Devolução de ativos na saída de colaboradores não assegurada','Quando um colaborador sai, o portátil, o telemóvel e os cartões de acesso nem sempre são devolvidos e registados.','Organizacional',ARRAY['Processo de offboarding informal','Falta de articulação entre recursos humanos e TI'],ARRAY['Equipamento com dados da organização fora do perímetro','Acessos físicos e lógicos ativos após a saída'],3,4,ARRAY['portatil','dispositivo movel','instalacao fisica'],ARRAY['A.5.11','A.6.5','A.5.18'],'ISO 27001',ARRAY['offboarding']),
('BIB-ORG-16','Ausência de gestão de riscos de segurança documentada','Os riscos não são identificados, avaliados nem tratados de forma estruturada, sendo as decisões tomadas por perceção individual.','Organizacional',ARRAY['Metodologia de risco inexistente','Falta de competências internas'],ARRAY['Investimento em segurança desalinhado das ameaças reais','Riscos críticos aceites sem decisão consciente'],4,4,ARRAY['pessoas'],ARRAY['A.5.1','A.5.2','A.5.8'],'Ambos',ARRAY['risco','governanca']),
('BIB-ORG-17','Segurança não considerada na gestão de projetos','Novos projetos e novas aplicações avançam sem requisitos de segurança definidos desde o início, sendo os controlos acrescentados no fim ou nunca.','Organizacional',ARRAY['Prazos agressivos','Equipas de projeto sem interlocutor de segurança'],ARRAY['Vulnerabilidades estruturais difíceis de corrigir mais tarde','Custos elevados de remediação'],4,3,ARRAY['aplicacao web','cloud/SaaS'],ARRAY['A.5.8','A.8.25','A.8.27'],'Ambos',ARRAY['projetos','sdlc']),
('BIB-ORG-18','Contactos com autoridades e entidades especializadas não estabelecidos','A organização não tem contactos definidos com autoridades competentes nem com entidades de resposta a incidentes, o que atrasa a atuação em crise.','Organizacional',ARRAY['Nunca ocorreu um incidente grave','Falta de plano de comunicação de crise'],ARRAY['Atraso na notificação obrigatória','Perda de apoio técnico externo em incidente grave'],3,3,ARRAY['pessoas'],ARRAY['A.5.5','A.5.6'],'Ambos',ARRAY['incidentes','autoridades']),
('BIB-ORG-19','Cobertura de seguro cibernético inexistente ou desadequada','Não existe apólice que cubra custos de resposta a incidentes, perda de exploração ou responsabilidade perante titulares de dados.','Organizacional',ARRAY['Risco cibernético não avaliado financeiramente','Requisitos da apólice não cumpridos pela organização'],ARRAY['Custo total do incidente suportado pela organização','Recusa de indemnização por incumprimento de requisitos'],3,4,ARRAY['pessoas'],ARRAY['A.5.29','A.5.24'],'ISO 27001',ARRAY['seguro','financeiro']),
('BIB-ORG-20','Indicadores e monitorização do desempenho da segurança inexistentes','Não são recolhidos indicadores sobre incidentes, vulnerabilidades, formação ou cumprimento de controlos, pelo que a gestão decide sem informação.','Organizacional',ARRAY['Ausência de recolha automatizada de métricas','Falta de definição de objetivos mensuráveis'],ARRAY['Melhoria contínua inexistente','Impossibilidade de demonstrar eficácia dos controlos'],4,2,ARRAY['pessoas','aplicacao web'],ARRAY['A.5.35','A.5.36','A.8.16'],'ISO 27001',ARRAY['metricas']),
('BIB-PES-01','Colaboradores sem verificação de antecedentes na contratação','As contratações, incluindo para funções com acesso a dados sensíveis, ocorrem sem qualquer verificação de referências ou de idoneidade proporcional ao cargo.','Pessoas',ARRAY['Processo de recrutamento sem etapa de verificação','Contratações urgentes'],ARRAY['Acesso privilegiado atribuído a pessoa não idónea','Risco acrescido de fraude interna'],2,4,ARRAY['pessoas'],ARRAY['A.6.1','A.6.2'],'ISO 27001',ARRAY['rh','onboarding']),
('BIB-PES-02','Contratos de trabalho sem cláusulas de confidencialidade','Os contratos e os acordos com prestadores não incluem obrigações de confidencialidade nem de proteção de dados após o termo da relação.','Pessoas',ARRAY['Modelos contratuais desatualizados','Prestadores contratados sem acordo escrito'],ARRAY['Divulgação de informação sem consequência jurídica clara','Perda de segredo comercial'],3,4,ARRAY['pessoas','fornecedor'],ARRAY['A.6.2','A.6.6','A.5.20'],'Ambos',ARRAY['rh','confidencialidade']),
('BIB-PES-03','Ausência de formação e sensibilização em segurança','Os utilizadores nunca receberam formação sobre phishing, palavras-passe, tratamento de dados pessoais ou reporte de incidentes.','Pessoas',ARRAY['Falta de plano anual de sensibilização','Segurança vista como assunto exclusivo de TI'],ARRAY['Elevada taxa de sucesso de ataques de engenharia social','Incidentes causados por erro humano evitável'],5,4,ARRAY['pessoas'],ARRAY['A.6.3','A.5.10','A.6.8'],'Ambos',ARRAY['formacao','sensibilizacao']),
('BIB-PES-04','Suscetibilidade a phishing e fraude do CEO','Mensagens de correio eletrónico fraudulentas induzem utilizadores a revelar credenciais ou a efetuar pagamentos para contas controladas por atacantes.','Pessoas',ARRAY['Ausência de simulações de phishing','Falta de dupla validação em pagamentos','Filtros de correio eletrónico permissivos'],ARRAY['Comprometimento de contas e acesso ao correio da organização','Perda financeira direta por transferência fraudulenta'],5,4,ARRAY['pessoas','estacao de trabalho'],ARRAY['A.6.3','A.8.23','A.5.24','A.8.7'],'ISO 27001',ARRAY['phishing','engenharia social']),
('BIB-PES-05','Processo disciplinar por violação de segurança inexistente','Não está previsto qualquer procedimento formal para tratar incumprimentos das regras de segurança, o que retira credibilidade às políticas.','Pessoas',ARRAY['Regulamento interno sem referência à segurança','Falta de articulação com recursos humanos'],ARRAY['Incumprimentos repetidos sem consequência','Dificuldade em defender medidas em tribunal'],3,3,ARRAY['pessoas'],ARRAY['A.6.4','A.5.10'],'ISO 27001',ARRAY['rh','disciplinar']),
('BIB-PES-06','Trabalho remoto sem regras nem proteções técnicas','Os utilizadores trabalham a partir de casa ou de espaços públicos sem VPN, sem cifra e sem regras sobre redes wi-fi e espaços partilhados.','Pessoas',ARRAY['Adoção acelerada do trabalho remoto','Ausência de política de teletrabalho'],ARRAY['Interceção de comunicações em redes não fiáveis','Visualização indevida de informação em espaços públicos'],4,3,ARRAY['portatil','dispositivo movel'],ARRAY['A.6.7','A.8.1','A.8.24','A.7.7'],'ISO 27001',ARRAY['teletrabalho']),
('BIB-PES-07','Canal de reporte de eventos de segurança desconhecido','Os utilizadores não sabem como nem a quem comunicar um evento suspeito, pelo que a maioria dos sinais precoces nunca chega à equipa de segurança.','Pessoas',ARRAY['Canal inexistente ou não divulgado','Receio de represálias'],ARRAY['Deteção tardia de incidentes em curso','Propagação de malware evitável'],4,3,ARRAY['pessoas'],ARRAY['A.6.8','A.5.24','A.6.3'],'ISO 27001',ARRAY['reporte','incidentes']),
('BIB-PES-08','Dependência crítica de uma única pessoa','O conhecimento e os acessos a sistemas essenciais estão concentrados numa única pessoa, sem substituto nem documentação.','Pessoas',ARRAY['Equipa reduzida','Ausência de documentação operacional','Falta de segregação de funções'],ARRAY['Paragem de operações em caso de ausência ou saída','Impossibilidade de controlo sobre a atuação dessa pessoa'],4,4,ARRAY['pessoas','servidor'],ARRAY['A.5.3','A.5.30','A.8.29'],'ISO 27001',ARRAY['dependencia','sucessao']),
('BIB-PES-09','Utilização não monitorizada de inteligência artificial generativa com dados pessoais','Colaboradores colocam documentos internos e dados pessoais em assistentes de IA públicos para acelerar tarefas, sem regras nem registo.','Pessoas',ARRAY['Ausência de política de utilização de IA','Ferramentas acessíveis a partir do navegador','Falta de alternativa aprovada pela organização'],ARRAY['Divulgação de dados pessoais e de segredos comerciais a terceiros','Tratamento sem base legal e sem informação aos titulares','Respostas incorretas usadas em decisões de negócio'],4,4,ARRAY['estacao de trabalho','cloud/SaaS','pessoas'],ARRAY['A.5.10','A.5.23','A.8.19','A.6.3','A.5.34'],'Ambos',ARRAY['ia','privacidade','shadow it']),
('BIB-PES-10','Ameaça interna: utilização indevida de acessos legítimos','Um colaborador com acesso legítimo copia ou divulga informação da organização, por motivação económica ou por conflito laboral.','Pessoas',ARRAY['Acessos excessivos face à função','Ausência de registos de acesso e de alertas','Saídas de colaboradores em conflito'],ARRAY['Fuga de carteira de clientes e de propriedade intelectual','Violação de dados pessoais com notificação obrigatória'],3,5,ARRAY['pessoas','estacao de trabalho','base de dados'],ARRAY['A.5.18','A.8.2','A.8.15','A.8.16','A.6.4'],'Ambos',ARRAY['insider','fuga de dados']),
('BIB-FIS-01','Perímetro físico sem controlo de acesso','As instalações não têm controlo de entrada eficaz, permitindo que pessoas não autorizadas circulem em áreas com equipamento e documentação sensível.','Fisico',ARRAY['Portas destrancadas durante o horário de expediente','Ausência de receção ou de registo de visitas'],ARRAY['Furto de equipamento e de documentos','Instalação de dispositivos maliciosos na rede'],3,4,ARRAY['instalacao fisica','estacao de trabalho'],ARRAY['A.7.1','A.7.2','A.7.3'],'ISO 27001',ARRAY['fisico','acesso']),
('BIB-FIS-02','Visitantes sem acompanhamento nem registo','As visitas circulam sem acompanhamento e não fica registo de quem entrou, quando e com que finalidade.','Fisico',ARRAY['Falta de procedimento de receção','Ausência de crachás de identificação'],ARRAY['Acesso não autorizado a áreas sensíveis','Impossibilidade de investigar ocorrências'],4,3,ARRAY['instalacao fisica'],ARRAY['A.7.2','A.7.3','A.7.6'],'ISO 27001',ARRAY['fisico','visitas']),
('BIB-FIS-03','Sala técnica sem proteção adequada','O bastidor com servidores e equipamento de rede está num espaço partilhado, sem fechadura dedicada, sem deteção de incêndio e sem controlo de temperatura.','Fisico',ARRAY['Falta de espaço adequado','Investimento adiado'],ARRAY['Avaria por sobreaquecimento','Manipulação física de servidores e de cópias de segurança'],3,5,ARRAY['servidor','rede/firewall','instalacao fisica'],ARRAY['A.7.3','A.7.4','A.7.5','A.7.8','A.7.11'],'ISO 27001',ARRAY['fisico','datacenter']),
('BIB-FIS-04','Ausência de proteção contra falha de energia','Os equipamentos críticos não estão ligados a fonte de alimentação ininterrupta nem a gerador, ficando expostos a quebras de corrente.','Fisico',ARRAY['UPS inexistente ou com baterias esgotadas','Ausência de manutenção preventiva'],ARRAY['Paragem abrupta com corrupção de dados','Indisponibilidade prolongada de serviços'],3,4,ARRAY['servidor','rede/firewall','NAS/armazenamento'],ARRAY['A.7.11','A.7.12','A.7.13','A.8.14'],'ISO 27001',ARRAY['energia','disponibilidade']),
('BIB-FIS-05','Cablagem de rede e elétrica desprotegida','As condutas de rede e de energia estão acessíveis e sem identificação, permitindo ligações não autorizadas ou danos acidentais.','Fisico',ARRAY['Instalações improvisadas','Ausência de etiquetagem e de documentação'],ARRAY['Interceção de tráfego por ligação não autorizada','Interrupções por desligamento acidental'],2,3,ARRAY['rede/firewall','instalacao fisica'],ARRAY['A.7.12','A.7.8'],'ISO 27001',ARRAY['fisico','rede']),
('BIB-FIS-06','Política de secretária e ecrã limpos não aplicada','Documentos confidenciais ficam sobre as secretárias e os computadores permanecem com sessão aberta e sem bloqueio automático.','Fisico',ARRAY['Falta de regra escrita e de sensibilização','Bloqueio automático de ecrã não configurado'],ARRAY['Leitura de informação confidencial por terceiros','Utilização indevida de sessões abertas'],4,3,ARRAY['estacao de trabalho','instalacao fisica'],ARRAY['A.7.7','A.7.6','A.8.1'],'ISO 27001',ARRAY['fisico','clean desk']),
('BIB-FIS-07','Equipamento fora das instalações sem proteção','Portáteis e discos externos são levados para casa, para clientes e para viagens sem regras de guarda, transporte e comunicação de perda.','Fisico',ARRAY['Ausência de regras para ativos fora do perímetro','Falta de registo de quem tem cada equipamento'],ARRAY['Furto em viatura ou em espaço público','Perda de informação sem possibilidade de recuperação'],3,4,ARRAY['portatil','dispositivo movel','NAS/armazenamento'],ARRAY['A.7.9','A.7.10','A.8.1','A.7.14'],'ISO 27001',ARRAY['fisico','mobilidade']),
('BIB-FIS-08','Suportes amovíveis sem controlo','Pens USB e discos externos são utilizados livremente para transportar ficheiros, sem cifra, sem registo e sem restrições nas estações de trabalho.','Fisico',ARRAY['Portas USB abertas por omissão','Ausência de alternativa segura de partilha'],ARRAY['Introdução de malware na rede interna','Extração e perda de grandes volumes de informação'],4,4,ARRAY['estacao de trabalho','portatil'],ARRAY['A.7.10','A.8.7','A.8.12','A.8.24'],'ISO 27001',ARRAY['suportes','usb']),
('BIB-FIS-09','Eliminação insegura de equipamento e de documentos','Computadores, discos e documentos em papel são descartados sem destruição segura da informação neles contida.','Fisico',ARRAY['Ausência de procedimento de abate','Recolha de resíduos por terceiros sem certificado'],ARRAY['Recuperação de dados pessoais a partir de discos descartados','Violação de dados com notificação obrigatória'],3,4,ARRAY['estacao de trabalho','portatil','NAS/armazenamento','instalacao fisica'],ARRAY['A.7.14','A.7.10','A.8.10'],'Ambos',ARRAY['eliminacao','residuos']),
('BIB-FIS-10','Manutenção de equipamento sem controlo de segurança','Intervenções técnicas em servidores e equipamentos são realizadas por terceiros sem acompanhamento nem registo do que foi feito ou retirado.','Fisico',ARRAY['Assistência prestada por fornecedores sem contrato de segurança','Ausência de registo de intervenções'],ARRAY['Substituição de discos com dados sem destruição','Introdução de alterações não autorizadas'],3,3,ARRAY['servidor','NAS/armazenamento','fornecedor'],ARRAY['A.7.13','A.7.14','A.5.20'],'ISO 27001',ARRAY['manutencao','fornecedores']);